<template>
  <section id="hero" class="hero">
    <div class="hero-grid">
      <!-- Left Column -->
      <div class="hero-left">
        <div class="hero-eyebrow">{{ heroLabel }}</div>

        <div class="name-block">
          <span class="name-line1" ref="nameRef">서상훈</span>
          <span class="name-line2" ref="devRef">.dev</span>
        </div>

        <p class="hero-tagline" v-html="taglineHtml" />

        <div class="term">
          <div class="term-bar">
            <div class="dd r"></div>
            <div class="dd y"></div>
            <div class="dd g"></div>
            <span class="term-title">seo@portfolio — zsh</span>
          </div>
          <div class="term-body">
            <div class="tl"><span class="pr">$</span><span class="tc">describe --role</span></div>
            <div class="tl indent">
              <span class="to">
                <span class="hl">{{ t('hero.roleTag1') }}</span>
                · <span class="hlb">{{ t('hero.roleTag2') }}</span>
                · <span class="hlp">{{ t('hero.roleTag3') }}</span>
              </span>
            </div>
            <div class="tl mt8"><span class="pr">$</span><span class="tc">ls ./achievements</span></div>
            <div class="tl indent">
              <span class="to">
                <span class="hl">api_200+</span>&nbsp;&nbsp;
                <span class="hlb">sso_4solutions</span>&nbsp;&nbsp;
                <span class="hlp">screen_30</span>&nbsp;&nbsp;
                <span class="hla">team_lead_8</span>
              </span>
            </div>
            <div class="tl mt8"><span class="pr">$</span><span class="tc">echo $PHILOSOPHY</span></div>
            <div class="tl indent">
              <span class="to">"<span class="hl">{{ t('hero.typed') }}</span>" <span class="blink"></span></span>
            </div>
          </div>
        </div>

        <div class="cta-row">
          <a href="#competency" class="btn btn-p">{{ t('hero.cta_primary') }}</a>
          <a href="mailto:seosh9369@gmail.com" class="btn btn-s">seosh9369@gmail.com</a>
        </div>
      </div>

      <!-- Right Column: Stat Cards -->
      <div class="hero-right">
        <div class="stat-deck">
          <div
            v-for="stat in stats"
            :key="stat.key"
            class="stat-card"
          >
            <div class="sc-top">
              <span class="sc-label">{{ t(`stats.${stat.key}`) }}</span>
              <span class="sc-icon">◈</span>
            </div>
            <div class="sc-num" :class="stat.color">
              <span class="cnt" :data-val="stat.val">0</span>{{ t(`stats.${stat.key}Unit`) }}
            </div>
            <div class="sc-desc">{{ t(`stats.${stat.key}Desc`) }}</div>
            <div class="sc-bar">
              <div class="sc-fill" :class="stat.color" :style="`--w:${stat.w}`"></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </section>
</template>

<script setup>
import { computed, ref, onMounted } from 'vue'
import { useI18n } from 'vue-i18n'

const { t, locale } = useI18n()

const nameRef = ref(null)
const devRef = ref(null)

const taglineHtml = computed(() =>
  t('hero.tagline').replace(/\n/g, '<br>')
)

const heroLabel = computed(() => {
  const now = new Date()
  const ny = now.getFullYear()
  const nm = now.getMonth() + 1 // 1-based

  // 실제 재직 기간만 합산 (공백 기간 제외), 시작월~종료월 포함 계산
  const periods = [
    { start: [2022, 6], end: [2023, 9]  }, // Epikar
    { start: [2023, 12], end: [2024, 2] }, // LG하이케어솔루션
    { start: [2024, 5], end: null        }, // AITStory (재직 중)
  ]

  const totalMonths = periods.reduce((sum, { start: [sy, sm], end }) => {
    const [ey, em] = end ?? [ny, nm]
    return sum + (ey - sy) * 12 + (em - sm) + 1
  }, 0)

  const years = Math.floor(totalMonths / 12)
  const months = totalMonths % 12
  const duration =
    locale.value === 'ko'
      ? `${years}년 ${months}개월+`
      : `${years}yr ${months}mo+`
  return `${t('hero.label')} · ${duration}`
})

const stats = [
  { key: 'api',       val: 200, color: 'green',  w: '95%' },
  { key: 'solutions', val: 4,   color: 'blue',   w: '40%' },
  { key: 'screens',   val: 30,  color: 'purple', w: '70%' },
  { key: 'migration', val: 100, color: 'amber',  w: '100%' },
]

onMounted(() => {
  /* Block-char glitch on name */
  const glitchChars = '█▓▒░▀▄┼╫'
  const orig = '서상훈'

  function runGlitch() {
    if (!nameRef.value) return
    let i = 0
    const iv = setInterval(() => {
      if (i < 3) {
        nameRef.value.textContent = Array.from(orig).map((c, j) =>
          j <= i ? glitchChars[Math.floor(Math.random() * glitchChars.length)] : c
        ).join('')
      } else {
        nameRef.value.textContent = orig
        clearInterval(iv)
      }
      i++
    }, 60)
  }
  setInterval(runGlitch, 5000)

  /* Counter animation */
  function counter(el, target, dur) {
    let s = 0
    const step = target / (dur / 16)
    const tm = setInterval(() => {
      s = Math.min(s + step, target)
      el.textContent = Math.round(s)
      if (s >= target) clearInterval(tm)
    }, 16)
  }

  const heroRight = document.querySelector('.hero-right')
  if (heroRight) {
    const cntObs = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.querySelectorAll('.cnt').forEach(el =>
            counter(el, +el.dataset.val, 1400)
          )
          cntObs.unobserve(entry.target)
        }
      })
    }, { threshold: 0.3 })
    cntObs.observe(heroRight)
  }

  /* 3D tilt on stat cards */
  document.querySelectorAll('.stat-card').forEach(card => {
    card.addEventListener('mousemove', e => {
      const r = card.getBoundingClientRect()
      const x = (e.clientX - r.left) / r.width - 0.5
      const y = (e.clientY - r.top) / r.height - 0.5
      card.style.transform = `perspective(600px) rotateY(${x * 8}deg) rotateX(${-y * 8}deg) translateX(-6px)`
    })
    card.addEventListener('mouseleave', () => {
      card.style.transform = ''
    })
  })
})
</script>

<style scoped>
/* Hero layout */
.hero {
  position: relative;
  z-index: 2;
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: 110px 52px 70px;
  max-width: 1280px;
  margin: 0 auto;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 480px;
  gap: 60px;
  align-items: center;
  width: 100%;
}

/* Eyebrow */
.hero-eyebrow {
  font-size: 11px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--g);
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  gap: 12px;
  opacity: 0;
  animation: fadeUp 0.8s 0.2s forwards;
}
.hero-eyebrow::before {
  content: '';
  display: block;
  width: 40px; height: 1px;
  background: linear-gradient(90deg, var(--g), transparent);
}

/* Name */
.name-block {
  margin-bottom: 24px;
  opacity: 0;
  animation: fadeUp 0.9s 0.4s forwards;
}
.name-line1 {
  font-family: var(--disp);
  font-size: clamp(64px, 9vw, 120px);
  font-weight: 800;
  line-height: 0.9;
  color: var(--tb);
  letter-spacing: -5px;
  display: block;
}
.name-line2 {
  font-family: var(--disp);
  font-size: clamp(64px, 9vw, 120px);
  font-weight: 800;
  line-height: 0.9;
  color: transparent;
  -webkit-text-stroke: 1px rgba(0,255,136,0.5);
  letter-spacing: -5px;
  display: block;
}

/* Tagline */
.hero-tagline {
  font-size: 15px;
  color: var(--t);
  max-width: 500px;
  line-height: 1.8;
  margin-bottom: 32px;
  opacity: 0;
  animation: fadeUp 0.9s 0.6s forwards;
}
.hero-tagline :deep(strong) { color: var(--g); font-weight: 500; }

/* Terminal */
.term {
  background: var(--bg2);
  border: 1px solid var(--br);
  border-radius: 8px;
  overflow: hidden;
  opacity: 0;
  animation: fadeUp 0.9s 0.8s forwards;
  box-shadow: 0 0 40px rgba(0,255,136,0.05);
  margin-bottom: 28px;
}
.term-bar {
  padding: 11px 16px;
  border-bottom: 1px solid var(--br);
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(0,255,136,0.02);
}
.dd { width: 11px; height: 11px; border-radius: 50%; }
.dd.r { background: #ff5f56; }
.dd.y { background: #ffbd2e; }
.dd.g { background: #27c93f; }
.term-title { font-size: 11px; color: var(--tm); margin-left: 8px; letter-spacing: 0.05em; }

.term-body { padding: 18px 22px; }
.tl { display: flex; gap: 10px; align-items: flex-start; margin-bottom: 3px; }
.tl.indent { padding-left: 24px; display: block; }
.tl.mt8 { margin-top: 8px; }
.pr { color: var(--g); min-width: 14px; font-size: 13px; flex-shrink: 0; }
.tc { font-size: 12px; color: var(--tb); }
.to { font-size: 12px; color: var(--tm); line-height: 1.7; }
.hl  { color: var(--g); }
.hlb { color: var(--b); }
.hlp { color: var(--p); }
.hla { color: var(--a); }

.blink {
  display: inline-block;
  width: 8px; height: 13px;
  background: var(--g);
  animation: cb 1s step-end infinite;
  vertical-align: middle;
  margin-left: 2px;
  border-radius: 1px;
}
@keyframes cb { 50% { opacity: 0; } }

/* CTA */
.cta-row {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  opacity: 0;
  animation: fadeUp 0.9s 1s forwards;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 13px 26px;
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.1em;
  text-decoration: none;
  border-radius: 4px;
  transition: all 0.3s;
  font-weight: 500;
  cursor: none;
}
.btn-p { background: var(--g); color: #000; border: none; }
.btn-p:hover { background: var(--gd); box-shadow: 0 0 24px rgba(0,255,136,0.4); transform: translateY(-3px); }
.btn-s { background: transparent; color: var(--t); border: 1px solid var(--br2); }
.btn-s:hover { border-color: var(--g); color: var(--g); box-shadow: 0 0 18px rgba(0,255,136,0.15); transform: translateY(-3px); }

/* Right: Stat Cards */
.hero-right {
  opacity: 0;
  animation: fadeLeft 1s 0.7s forwards;
}
.stat-deck { display: flex; flex-direction: column; gap: 12px; }

.stat-card {
  background: var(--bg2);
  border: 1px solid var(--br);
  border-radius: 8px;
  padding: 20px 24px;
  transition: all 0.4s;
  transform-style: preserve-3d;
  position: relative;
  overflow: hidden;
  cursor: none;
}
.stat-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(0,255,136,0.04) 0%, transparent 50%);
  opacity: 0;
  transition: opacity 0.3s;
}
.stat-card:hover { border-color: var(--br2); box-shadow: -4px 0 20px rgba(0,255,136,0.1); }
.stat-card:hover::before { opacity: 1; }

.sc-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 10px;
}
.sc-label { font-size: 10px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--tm); }
.sc-icon { font-size: 13px; color: var(--br2); }

.sc-num {
  font-family: var(--disp);
  font-size: 38px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: -2px;
}
.sc-num.green  { color: var(--g); text-shadow: 0 0 16px rgba(0,255,136,0.3); }
.sc-num.blue   { color: var(--b); text-shadow: 0 0 16px rgba(56,189,248,0.3); }
.sc-num.purple { color: var(--p); text-shadow: 0 0 16px rgba(167,139,250,0.3); }
.sc-num.amber  { color: var(--a); text-shadow: 0 0 16px rgba(255,179,71,0.3); }

.sc-desc { font-size: 11px; color: var(--tm); margin-top: 6px; }

.sc-bar { height: 2px; background: var(--bg3); border-radius: 1px; margin-top: 10px; overflow: hidden; }
.sc-fill { height: 100%; border-radius: 1px; animation: barGrow 1.5s 1.5s ease both; }
@keyframes barGrow { from { width: 0; } to { width: var(--w, 100%); } }
.sc-fill.green  { background: linear-gradient(90deg, var(--g), var(--gd)); box-shadow: 0 0 6px var(--g); }
.sc-fill.blue   { background: linear-gradient(90deg, var(--b), #0ea5e9);  box-shadow: 0 0 6px var(--b); }
.sc-fill.purple { background: linear-gradient(90deg, var(--p), #8b5cf6);  box-shadow: 0 0 6px var(--p); }
.sc-fill.amber  { background: linear-gradient(90deg, var(--a), #f59e0b);  box-shadow: 0 0 6px var(--a); }

/* Animations */
@keyframes fadeUp   { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
@keyframes fadeLeft { from { opacity: 0; transform: translateX(40px); } to { opacity: 1; transform: translateX(0); } }

/* Mobile */
@media (max-width: 900px) {
  .hero { padding: 110px 24px 60px; }
  .hero-grid { grid-template-columns: 1fr; gap: 48px; }
  .hero-right { display: none; }
}
@media (max-width: 480px) {
  .hero { padding: 100px 16px 60px; }
  .name-line1, .name-line2 { letter-spacing: -3px; }
  .hero-tagline { font-size: 13px; }
  .term-body { padding: 14px 16px; }
}
</style>
