<template>
  <div class="chatbot-root">

    <!-- Notification Bubble -->
    <Transition name="bubble">
      <div class="chat-bubble" v-if="showBubble" @click="openChat">
        {{ t('chatbot.bubble') }}
      </div>
    </Transition>

    <!-- FAB Button -->
    <button
      class="chat-fab"
      :class="{ active: isOpen }"
      @click="toggleChat"
      :aria-label="t('chatbot.title')"
    >
      <svg v-if="!isOpen" width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
        <path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"/>
      </svg>
      <span v-else class="fab-x">✕</span>
    </button>

    <!-- Chat Modal -->
    <Transition name="chat-modal">
      <div class="chat-modal" v-if="isOpen">

        <!-- Terminal Header -->
        <div class="chat-header">
          <div class="chat-dots">
            <span class="dot r"></span>
            <span class="dot y"></span>
            <span class="dot g"></span>
          </div>
          <span class="chat-title">{{ t('chatbot.title') }}</span>
        </div>

        <!-- Messages -->
        <div class="chat-messages" ref="messagesRef">

          <!-- Welcome message -->
          <div class="msg msg-ai">
            <span class="msg-pfx ai-pfx">AI</span>
            <p class="msg-text">{{ t('chatbot.welcome') }}</p>
          </div>

          <!-- History -->
          <template v-for="(msg, i) in messages" :key="i">
            <div :class="['msg', msg.role === 'user' ? 'msg-user' : 'msg-ai']">
              <span :class="['msg-pfx', msg.role === 'user' ? 'user-pfx' : 'ai-pfx']">
                {{ msg.role === 'user' ? 'YOU' : 'AI' }}
              </span>
              <p class="msg-text">{{ msg.content }}</p>
            </div>
          </template>

          <!-- Typing indicator -->
          <div class="msg msg-ai" v-if="isTyping">
            <span class="msg-pfx ai-pfx">AI</span>
            <div class="typing">
              <span></span><span></span><span></span>
            </div>
          </div>

        </div>

        <!-- Quick Question Buttons -->
        <div class="quick-wrap">
          <button
            v-for="(key, i) in quickKeys"
            :key="i"
            class="quick-btn"
            :class="{ used: usedSet.has(i) }"
            :disabled="usedSet.has(i) || isTyping"
            @click="askQuestion(i)"
          >
            {{ t(key) }}
          </button>
        </div>

      </div>
    </Transition>

  </div>
</template>

<script setup>
import { ref, nextTick, onMounted } from 'vue'
import { useI18n } from 'vue-i18n'

const { t, locale } = useI18n()

// ── Q&A 데이터 (서버 없음, 정적) ─────────────────────────────────────────
const qa = [
  {
    ko: '기업 내부 IdP에서 WebSocket으로 사용자 정보를 수신하고, 포털이 Identity Broker로서 솔루션별 개별 Signature JWT를 발급하는 Token Relay 구조를 설계했습니다. 자사 솔루션의 추가 API 개발 부담을 최소화하면서 보안 기준을 충족하기 위해 솔루션별 Signature 분리 + aud Claim 이중 격리 방식을 선택했습니다.',
    en: 'I designed a Token Relay architecture where the internal IdP sends user info via WebSocket, and the portal acts as an Identity Broker issuing individual Signature-based JWTs per solution. I chose per-solution Signature separation plus aud Claim double isolation to minimize integration burden on internal solutions while meeting security standards.',
  },
  {
    ko: '8인 팀에서 아키텍처 설계, 개발 컨벤션 수립, 코드 리뷰 전담, 서버 설정까지 전반을 주도했습니다. PR 기반 코드 리뷰 문화를 처음부터 만들었고, 전체 개발자 회의 참여로 기획 단계부터 기술 의사결정에 직접 기여했습니다.',
    en: 'I led architecture design, dev convention setup, full code review ownership, and server configuration for an 8-person team. I introduced PR-based code review culture from scratch and participated in developer meetings to contribute to technical decisions from the planning stage.',
  },
  {
    ko: 'Epikar에서 하드웨어 이슈로 주행기록-차량 매핑 데이터가 손상된 상황이었습니다. 전체 재수집 시 정상 데이터 오염 위험이 있어서, 무결성 검증 후 오류 건만 선별 복원하고 방어 로직을 2주 내 배포했습니다.',
    en: 'At Epikar, hardware issues caused corruption in driving record–vehicle mapping data. Since full re-collection risked contaminating valid data, I validated integrity, selectively recovered only erroneous records, and deployed defensive logic within 2 weeks.',
  },
  {
    ko: 'Vue3, TypeScript, Spring Boot, Oracle, Redis, K8S, Docker입니다. 삼성카드 프로젝트에서 프론트부터 백엔드, 인프라까지 전 구간을 직접 다뤘습니다. Vue2→Vue3, Spring Boot 2.7→3.1 마이그레이션도 API 무결성 100% 유지하며 수행했습니다.',
    en: 'Vue3, TypeScript, Spring Boot, Oracle, Redis, K8S, Docker. On the Samsung Card project, I handled everything from frontend to backend and infrastructure. I also performed a Vue2→Vue3, Spring Boot 2.7→3.1 migration with 100% API integrity maintained.',
  },
  {
    ko: '왜 이 구조인가를 먼저 고민하는 개발자입니다. 구현보다 설계, 기능보다 트레이드오프를 먼저 생각합니다. 삼성카드 프로젝트에서 인증 아키텍처를 처음부터 설계하고 팀 기술 기준을 만든 경험이 그 방향을 확신하게 해줬습니다.',
    en: "I'm a developer who thinks about 'why this structure' before anything else. I prioritize design over implementation, and trade-offs over features. Designing the auth architecture from scratch and establishing team tech standards on the Samsung Card project solidified that direction for me.",
  },
]

const quickKeys = [
  'chatbot.quick1',
  'chatbot.quick2',
  'chatbot.quick3',
  'chatbot.quick4',
  'chatbot.quick5',
]

// ── 상태 ─────────────────────────────────────────────────────────────────
const isOpen     = ref(false)
const showBubble = ref(false)
const messages   = ref([])
const isTyping   = ref(false)
const usedSet    = ref(new Set())
const messagesRef = ref(null)

onMounted(() => {
  setTimeout(() => {
    showBubble.value = true
    setTimeout(() => { showBubble.value = false }, 3000)
  }, 2000)
})

function openChat() {
  isOpen.value    = true
  showBubble.value = false
}

function toggleChat() {
  isOpen.value    = !isOpen.value
  showBubble.value = false
}

async function askQuestion(idx) {
  if (usedSet.value.has(idx) || isTyping.value) return

  const question = t(quickKeys[idx])
  messages.value.push({ role: 'user', content: question })
  usedSet.value = new Set(usedSet.value).add(idx)
  isTyping.value = true
  await scrollBottom()

  setTimeout(async () => {
    isTyping.value = false
    const lang   = locale.value === 'en' ? 'en' : 'ko'
    const answer = qa[idx][lang]
    messages.value.push({ role: 'assistant', content: answer })
    await scrollBottom()
  }, 800)
}

async function scrollBottom() {
  await nextTick()
  if (messagesRef.value) {
    messagesRef.value.scrollTop = messagesRef.value.scrollHeight
  }
}
</script>

<style scoped>
/* ── Root ── */
.chatbot-root {
  position: fixed;
  bottom: 32px;
  right: 32px;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
}

/* ── Notification Bubble ── */
.chat-bubble {
  background: var(--bg2);
  border: 1px solid var(--g);
  color: var(--t);
  font-size: 11.5px;
  font-family: var(--mono);
  padding: 8px 16px;
  border-radius: 16px 16px 4px 16px;
  white-space: nowrap;
  cursor: pointer;
  box-shadow: 0 0 20px rgba(0,255,136,0.18);
  transition: box-shadow 0.2s;
}
.chat-bubble:hover { box-shadow: 0 0 28px rgba(0,255,136,0.32); }

/* ── FAB ── */
.chat-fab {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--g);
  color: #000;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s;
  box-shadow: 0 4px 18px rgba(0,255,136,0.38);
  flex-shrink: 0;
}
.chat-fab:hover {
  transform: scale(1.1);
  box-shadow: 0 6px 26px rgba(0,255,136,0.52);
}
.chat-fab.active {
  background: var(--bg2);
  color: var(--g);
  border: 1px solid var(--g);
}
.fab-x { font-size: 15px; font-weight: 700; line-height: 1; }

/* ── Modal ── */
.chat-modal {
  width: 280px;
  height: 420px;
  background: var(--bg2);
  border: 1px solid var(--br);
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba(0,0,0,0.6), 0 0 0 1px var(--br2);
}

/* ── Terminal Header ── */
.chat-header {
  flex-shrink: 0;
  padding: 10px 14px;
  border-bottom: 1px solid var(--br);
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(0,255,136,0.02);
}
.chat-dots { display: flex; gap: 5px; }
.dot { width: 10px; height: 10px; border-radius: 50%; }
.dot.r { background: #ff5f56; }
.dot.y { background: #ffbd2e; }
.dot.g { background: #27c93f; }
.chat-title {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--tm);
  letter-spacing: 0.06em;
  flex: 1;
  text-align: center;
}

/* ── Messages ── */
.chat-messages {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  scrollbar-width: thin;
  scrollbar-color: var(--br) transparent;
}
.chat-messages::-webkit-scrollbar { width: 2px; }
.chat-messages::-webkit-scrollbar-thumb { background: var(--br2); }

.msg {
  display: flex;
  gap: 7px;
  align-items: flex-start;
}
.msg-pfx {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  font-weight: 700;
  flex-shrink: 0;
  padding-top: 3px;
}
.ai-pfx   { color: var(--g); }
.user-pfx { color: var(--b); }

.msg-text {
  font-size: 11.5px;
  line-height: 1.7;
  word-break: break-word;
  white-space: pre-line;
}
.msg-ai  .msg-text { color: var(--t); }
.msg-user { flex-direction: row-reverse; }
.msg-user .msg-text {
  color: var(--tb);
  background: rgba(56,189,248,0.07);
  border: 1px solid rgba(56,189,248,0.18);
  border-radius: 8px 2px 8px 8px;
  padding: 6px 10px;
}

/* ── Typing Indicator ── */
.typing {
  display: flex;
  gap: 4px;
  align-items: center;
  padding: 6px 0;
}
.typing span {
  width: 6px; height: 6px;
  background: var(--g);
  border-radius: 50%;
  animation: tdot 1.1s ease-in-out infinite;
}
.typing span:nth-child(2) { animation-delay: 0.18s; }
.typing span:nth-child(3) { animation-delay: 0.36s; }
@keyframes tdot {
  0%, 80%, 100% { transform: translateY(0);    opacity: 0.3; }
  40%           { transform: translateY(-7px); opacity: 1;   }
}

/* ── Quick Questions ── */
.quick-wrap {
  flex-shrink: 0;
  padding: 6px 10px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  border-top: 1px solid var(--br);
}
.quick-btn {
  font-size: 10px;
  font-family: var(--mono);
  color: var(--tm);
  background: var(--bg3);
  border: 1px solid var(--br);
  border-radius: 4px;
  padding: 6px 10px;
  text-align: left;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.quick-btn:hover:not(:disabled):not(.used) {
  border-color: var(--g);
  color: var(--g);
  background: rgba(0,255,136,0.04);
}
.quick-btn.used,
.quick-btn:disabled {
  opacity: 0.3;
  cursor: default;
}

/* ── Transitions ── */
.bubble-enter-active, .bubble-leave-active { transition: all 0.3s ease; }
.bubble-enter-from, .bubble-leave-to       { opacity: 0; transform: translateY(8px); }

.chat-modal-enter-active { transition: all 0.35s cubic-bezier(0.34, 1.56, 0.64, 1); }
.chat-modal-leave-active { transition: all 0.2s ease; }
.chat-modal-enter-from   { opacity: 0; transform: translateY(24px) scale(0.92); }
.chat-modal-leave-to     { opacity: 0; transform: translateY(12px) scale(0.96); }

/* ── Mobile ── */
@media (max-width: 480px) {
  .chatbot-root { bottom: 20px; right: 16px; }
  .chat-modal   { width: calc(100vw - 32px); }
}
</style>
