<template>
  <div class="sec-bg-wrap" data-section="projects">
    <div class="sec-divider"></div>
    <section id="projects" class="sec">
    <div class="sec-head">
      <span class="sec-tag">{{ t('projects.tag') }}</span>
      <h2 class="sec-title">{{ t('projects.title') }}</h2>
    </div>
    <div class="proj-card reveal">
      <div class="proj-body">
        <div class="proj-ctx">{{ t('projects.nypc.context') }}</div>
        <div class="proj-title">{{ t('projects.nypc.title') }}</div>
        <p class="proj-desc">{{ t('projects.nypc.desc') }}</p>
        <div class="etags">
          <span v-for="tag in tm('projects.nypc.tags')" :key="tag" class="etag">{{ tag }}</span>
        </div>
      </div>
      <a href="https://youtu.be/ql0lFXHtAnk" target="_blank" class="proj-link">
        ▶ {{ t('projects.nypc.link') }}
      </a>
    </div>
    </section>
  </div>
</template>

<script setup>
import { onMounted } from 'vue'
import { useI18n } from 'vue-i18n'

const { t, tm } = useI18n()

onMounted(() => {
  const observer = new IntersectionObserver(
    ([entry]) => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible')
        observer.unobserve(entry.target)
      }
    },
    { threshold: 0.1 }
  )
  document.querySelectorAll('.proj-card.reveal').forEach(el => observer.observe(el))
})
</script>

<style scoped>
/* ── Section Background ── */
.sec-bg-wrap {
  position: relative;
  width: 100%;
  background:
    radial-gradient(ellipse 50% 60% at 80% 50%, rgba(255,179,71,0.04), transparent),
    #07080a;
}
.sec-bg-wrap::before {
  content: '';
  position: absolute;
  left: 0; top: 10%; width: 3px; height: 80%;
  background: #ffb347;
  border-radius: 0 2px 2px 0;
  z-index: 3;
}

.sec {
  position: relative;
  z-index: 2;
  padding: 80px 48px;
  max-width: 1200px;
  margin: 0 auto;
}
.sec-head {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 56px;
}
.sec-tag {
  font-size: 10px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--g);
  background: var(--gb);
  border: 1px solid var(--br2);
  padding: 5px 14px;
  border-radius: 2px;
}
.sec-title {
  font-family: var(--disp);
  font-size: 36px;
  font-weight: 800;
  color: var(--tb);
  letter-spacing: -1.5px;
}
.proj-card {
  background: var(--bg2);
  border: 1px solid var(--br);
  border-radius: 6px;
  padding: 34px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 24px;
  align-items: start;
  transition: all 0.3s;
  position: relative;
  overflow: hidden;
}
.proj-card::before {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--g), var(--b), var(--p));
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.4s;
}
.proj-card:hover { border-color: var(--br2); }
.proj-card:hover::before { transform: scaleX(1); }

.proj-ctx {
  font-size: 10px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--a);
  margin-bottom: 8px;
}
.proj-title {
  font-family: var(--disp);
  font-size: 20px;
  font-weight: 700;
  color: var(--tb);
  margin-bottom: 12px;
}
.proj-desc {
  font-size: 13px;
  color: var(--t);
  line-height: 1.75;
  margin-bottom: 16px;
}
.etags { display: flex; flex-wrap: wrap; gap: 8px; }
.etag {
  font-size: 11px;
  padding: 3px 10px;
  border: 1px solid var(--br);
  border-radius: 2px;
  color: var(--tm);
  cursor: default;
}
.proj-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--b);
  text-decoration: none;
  border-bottom: 1px solid rgba(79,163,224,0.3);
  padding-bottom: 1px;
  transition: all 0.2s;
  white-space: nowrap;
}
.proj-link:hover { color: var(--g); border-color: var(--g); }

@media (max-width: 720px) {
  .sec { padding: 60px 16px; }
  .sec-title { font-size: 24px; }
  .proj-card { grid-template-columns: 1fr; }
}
</style>
